                meaningBn = "\"হে আমাদের রব্ব! আর আপনার জন্যই সমস্ত প্রশংসা; অঢেল, পবিত্র ও বরকত-রয়েছে-এমন প্রশংসা।\"",
                fojilotBn = "📖 সহীহ বুখারীর আলোকে অলৌকিক ফজিলত ও মর্যাদা:\n১. ৩০ জনের অধিক ফেরেশতার প্রতিযোগিতা: হযরত রিফা'আ ইবনে রাফে' (রা.) বর্ণনা করেন: একদিন আমরা নবীজী (ﷺ)-এর পেছনে সালাত আদায় করছিলাম। তিনি রুকু থেকে মাথা তুলে বললেন 'সামি'আল্লাহু লিমান হামিদাহ'। পেছনের এক সাহাবী বললেন: 'রব্বানা ওয়া লাকাল হামদু হামদান কাছীরান ত্বাইয়্যিবান মুবারাকান ফীহ'। সালাত শেষে নবীজী জিজ্ঞেস করলেন: \"এ কথাটি কে বলেছিলে?\" লোকটি বললেন: \"আমি, ইয়া রাসূলাল্লাহ!\" তখন নবীজী (ﷺ) বললেন: \"আমি দেখলাম ত্রিশ জনেরও বেশি ফেরেশতা প্রতিযোগিতা করছেন—কে তাদের মধ্যে এটি আগে আল্লাহর দরবারে লিপিবদ্ধ করবেন!\"\n২. হিসনুল মুসলিমের রুকু থেকে উঠার দো'আ #২: রুকু থেকে উঠে পুরোপুরি সোজা হয়ে দাঁড়িয়ে শান্তভাবে এই প্রশংসাবাক্য উচ্চারণ করা অত্যন্ত বরকতময় সুন্নাত।",
