                pronunciationBn = "আল্লা-হুম্মা ইন্নী আ'ঊযু বিকা মিন 'আযা-বি জাহান্নাম, ওয়া মিন 'আযা-বিল ক্বাবরি, ওয়া মিন ফিতনাতিল মাহইয়া- ওয়াল মামা-তি, ওয়া মিন শাররি ফিতনাতিল মাসীহিদ দাজ্জা-ল।",
                meaningBn = "\"হে আল্লাহ! নিশ্চয়ই আমি আপনার কাছে জাহান্নামের আযাব থেকে আশ্রয় চাই, কবরের আযাব থেকে আশ্রয় চাই, জীবন ও মৃত্যুর ফিতনা থেকে আশ্রয় চাই এবং ভণ্ড দাজ্জালের মারাত্মক ফিতনার অনিষ্ট থেকে আশ্রয় চাই।\"",
                fojilotBn = "📖 সহীহ মুসলিমের বর্ণনায় গুরুত্ব:\n১. তাউস (রহ.)-এর কঠোর আমল: তাবেয়ী তাউস (রহ.) তাঁর ছেলেকে জিজ্ঞেস করলেন: তুমি কি সালাতে শেষ বৈঠকে এই দো'আটি পড়েছ? ছেলে বললেন: না। তিনি বললেন: তবে সালাত পুনরায় আদায় করো! কোনো কোনো ফকীহ এ দো'আকে ওয়াজিব বলেছেন।\n২. নবীজী (ﷺ)-এর কঠোর তাগিদ: রাসূলুল্লাহ (ﷺ) বলেছেন: \"যখন তোমাদের কেউ শেষ তাশাহহুদ পাঠ সমাপ্ত করবে, সে যেন চারটি বস্তু থেকে আল্লাহর পানাহ চায়: জাহান্নাম, কবর, জীবন-মৃত্যুর ফিতনা ও মাসীহুদ দাজ্জাল।\"",
                detailsBn = "সালাতের সালাম ফেরানোর পূর্বমুহূর্তে দো'আ কবুল হয়। তাই তাশাহহুদ ও দরূদ পড়ার পর এই দো'আটি কখনই পরিত্যাগ করা উচিত নয়।",
                referenceBn = "সহীহ মুসলিম: ৫৮৮, ৫৮৯; সহীহ বুখারী: ১৩৭৭; সুনান আবু দাউদ: ৯৮৩"
            ),

            // ১৯. নামাজে বিভিন্ন চিন্তা বা ওয়াসওয়াসা আসলে করণীয় — একাগ্রতার ৬টি মূলভিত্তি
            IslamicLifeCardItem(
                id = "sd_salat_khushu_six_pillars",
                serialNumberBn = "১৯",
                repetitionOrTimeBn = "মনোযোগ ফিরানোর আমল ও ফিকহী গাইড",
                titleBn = "১৯. নামাজে বিভিন্ন চিন্তা বা ওয়াসওয়াসা আসলে করণীয় — একাগ্রতার ৬টি মূলভিত্তি",
                subtitleBn = "সালাতে শয়তানের ছিনতাইকর্ম প্রতিহত করা ও মন স্থির করার সুন্নাত ও ফিকহী নীতিমালা",
                arabicText = "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ۞ إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ",
                pronunciationBn = "আ'ঊযু বিল্লা-হি মিনাশ শায়ত্বা-নির রাজীম। ইন্নাছ ছলা-তা তানহা- 'আনিল ফাহশা-য়ি ওয়াল মুনকার।",
                meaningBn = "\"আমি বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় প্রার্থনা করছি। নিশ্চয়ই সালাত অশ্লীল ও গর্হিত কাজ থেকে বিরত রাখে।\" [সূরা আল-'আনকাবূত: ৪৫]",
                fojilotBn = "📖 নামাজে একাগ্রতা (খুশু-খুজু) অর্জনে ইমাম গাজালী (রহ.) ও সহীহ হাদিসের আলোকে ৬টি মূলভিত্তি:\n\n১. নামাজে ‘হুজুরে দিল’ বা অন্তরের উপস্থিতি:\nএটি নামাজের প্রাণ। রাসূলুল্লাহ (ﷺ) বলেছেন: \"আল্লাহর ইবাদত করো এমনভাবে, যেন তাঁকে তুমি দেখতে পাচ্ছ। আর যদি দেখতে না পাও, তবে তিনি যেন তোমাকে দেখছেন\" (সহীহ বুখারী: ৫০, মুসলিম: ৮)। আমাদের মন কখনো বেকার থাকে না; নামাজে দাঁড়ালে শয়তান মন ছিনিয়ে নিতে চায় (সহীহ বুখারী: ৩২৯১)। তাই রুকু, সিজদা বা বসার প্রতিটি পরিবর্তনের পূর্বে খেয়াল করুন 'আল্লাহ আমাকে দেখছেন'—কল্পনাটি আছে কি না। নবীজী (ﷺ) বলেন: \"যে সুন্দরভাবে অজু করে একাগ্রতার সাথে দুই রাকআত নামাজ আদায় করে, তার সমস্ত পূর্বের গুনাহ মাফ করে দেওয়া হয় এবং তার জন্য জান্নাত ওয়াজিব হয়ে যায়\" (নাসাঈ: ১৫১, বুখারী: ১৯৩৪, মুসলিম: ২২৮)।\n\n২. অর্থ বুঝে বিশুদ্ধ উচ্চারণে পাঠ করা:\nআল্লাহ তা'আলা বলেন: 'স্পষ্টভাবে ধীরে ধীরে কুরআন তেলাওয়াত করো' (সূরা মুযযাম্মিল: ৪)। রাসূলুল্লাহ (ﷺ) তারতীল সহকারে তেলাওয়াত করতেন (মুসলিম: ৭৩৩)। বিশেষ করে সূরা ফাতিহা পাঠের সময় স্মরণ করুন আল্লাহ প্রতিটি বাক্যের জবাবে আপনার সাথে কথা বলছেন (হাদীসে কুদসী - সহীহ মুসলিম: ৩৯৫)।\n\n৩. আল্লাহর প্রতি ‘তাযীম’ বা ভক্তি-শ্রদ্ধা প্রদর্শন:\nআল্লাহ নির্দেশ দিয়েছেন: 'তোমরা আল্লাহর সম্মুখে বিনীতভাবে দণ্ডায়মান হও' (বাকারা: ২৩৮)। আবু ক্বাতাদা (রা.) হতে বর্ণিত, রাসূলুল্লাহ (ﷺ) বলেছেন: \"নিকৃষ্টতম চোর হলো সেই ব্যক্তি, যে নামাজে চুরি করে। সাহাবীগণ বললেন: হে আল্লাহর রাসূল! নামাজে কীভাবে চুরি করে? তিনি বললেন: যে রুকু ও সিজদা পূর্ণভাবে আদায় করে না\" (মুসনাদে আহমাদ, মিশকাত: ৮৮৫)।\n\n৪. জীবনের শেষ নামাজ মনে করে আল্লাহকে ভয় করা:\nরাসূলুল্লাহ (ﷺ) উপদেশ দেন: \"যখন তুমি নামাজে দণ্ডায়মান হবে, তখন এমনভাবে নামাজ আদায় করো যেন এটিই তোমার জীবনের শেষ নামাজ\" (সুনান ইবনু মাজাহ: ৪১৭২, সনদ হাসান)।\n\n৫. সালাতের মাধ্যমে সাহায্য ও পরম করুণা প্রত্যাশা করা:\nআল্লাহ বলেন: 'তোমরা ধৈর্য ও সালাতের মাধ্যমে সাহায্য প্রার্থনা করো' (বাকারা: ৪৫)। নবীজী (ﷺ) বলেছেন: \"তোমাদের কেউ নামাজে দাঁড়ালে সে মূলত তার প্রভুর সাথে সরাসরি কথোপকথন করে\" (মুস্তাদরাক হাকেম, সহীহুল জামি': ১৫৩৮)।\n\n৬. নিজের গুনাহর কথা ভেবে 'হায়া' ও লজ্জা নিয়ে দাঁড়ানো:\nএকজন অপরাধীর মতো মস্তক অবনত রেখে দৃষ্টি সর্বদা সিজদার স্থানে নিবদ্ধ রাখুন। রাসূলুল্লাহ (ﷺ) দাঁড়ানো অবস্থায় দৃষ্টি সিজদার জায়গায় রাখতেন (তাফসীরে তাবারী: ৯/১৯৭)।\n\n★ তাৎক্ষণিক ওয়াসওয়াসা দূর করার সুন্নাত আমল:\nসালাতের মাঝে শয়তান মনে বিভ্রান্তি সৃষ্টি করলে বাম দিকে তিনবার হালকা থুতুর ভাব করে বলুন: 'আ'ঊযু বিল্লা-হি মিনাশ শায়ত্বা-নির রাজীম'। নবীজী (ﷺ) এই শয়তানের নাম বলেছেন 'খিনযাব' (সহীহ মুসলিম: ২২০৩)।",
                detailsBn = "এই ৬টি বিষয় নিয়মিত অনুশীলন করলে সালাত প্রাণবন্ত হবে এবং দুনিয়াবী চিন্তা থেকে মন সম্পূর্ণ মুক্ত হয়ে আল্লাহর রহমতের সাগরে অবগাহন করবে।",
