                fojilotBn = "📖 কুরআন ও সহীহ হাদিসের আলোকে সালাতের ওয়াক্ত রক্ষা ও জবাবদিহিতার বিধান:\n\n১. আল্লাহর নিকট সর্বাধিক প্রিয় আমল:\nহযরত আব্দুল্লাহ ইবনু মাসঊদ (রা.) বলেন, আমি রাসূলুল্লাহ (ﷺ)-কে জিজ্ঞেস করলাম: আল্লাহর কাছে সবচেয়ে প্রিয় আমল কোনটি? নবীজী ইরশাদ করলেন: 'الصَّلَاةُ عَلَى وَقْتِهَا — সময়মতো সঠিক ওয়াক্তে সালাত আদায় করা' (সহীহ বুখারী: ৫২৭, সহীহ মুসলিম: ৮৫)। সালাতকে তার মুস্তাহাব প্রথম ওয়াক্তে (আউয়াল ওয়াক্তে) আদায় করাই নববী সুন্নাত।\n\n২. সালাত ওয়াক্ত থেকে পিছিয়ে দেওয়ার ব্যাপারে কঠোর নববী সতর্কবার্তা:\nহযরত আবূ যার (রা.) হতে বর্ণিত, রাসূলুল্লাহ (ﷺ) আমাকে বললেন: \"সে সময় তুমি কী করবে যখন তোমাদের ওপর এমন শাসক হবে, যারা সালাতকে তার সময় থেকে পিছিয়ে দেবে কিংবা সালাতকে মেরে ফেলবে?\" আমি বললাম: আপনি আমাকে কী আদেশ করেন? নবীজী (ﷺ) বললেন: \"তুমি তোমার সালাত সঠিক সময়ে (ওয়াক্তের শুরুতে) আদায় করে নেবে। অতঃপর তাদের সাথে সালাত পেলে আবার আদায় করবে, আর এ সালাত তোমার জন্য নফল হিসেবে গণ্য হবে\" (সহীহ মুসলিম: ৬৪৮; সুনান আবু দাউদ: ৪৩১; মিশকাতুল মাসাবীহ: ৬০০)।\n\n৩. ওয়াক্ত নষ্টকারীদের জন্য জাহান্নামের 'ওয়াইল' শাস্তি:\nমুফাসসিরিনদের সর্বসম্মত মতে, সূরা মা'উনে বর্ণিত 'ওয়াইল' বা দুর্ভোগ হলো সেই সব ব্যক্তির জন্য যারা সালাত একেবারে ত্যাগ করে না বটে, তবে আলসেমি করে সময় পার করে শেষ মুহূর্তে সালাত পড়ে।",
                detailsBn = "সালাতের ওয়াক্ত রক্ষা করা এবং প্রথম ওয়াক্তে জামা'আতের সাথে আদায় করা মুমিনের সার্বিক আমল কবুল হওয়ার প্রধান শর্ত।",
                referenceBn = "সূরা আন-নিসা: ১০৩; সূরা আল-মা'উন: ৪-৫; সহীহ বুখারী: ৫২৭; সহীহ মুসলিম: ৮৫, ৬৪৮; সুনান আবু দাউদ: ৪৩১; মিশকাতুল মাসাবীহ: ৬০০"
