                pronunciationBn = "ক্বাদ্ আফলাহাল মু'মিনূন। আল্লাযীনা হুম ফী সলা-তিহিম খা-শি'ঊন।",
                meaningBn = "\"নিশ্চয়ই মুমিনগণ সফলকাম হয়েছে—যারা তাদের সালাতে বিনম্র ও একাগ্র (খুশুসম্পন্ন)।\" [সূরা আল-মু'মিনূন: ১-২]",
                fojilotBn = "📖 সালাতের শারীরিক বিশুদ্ধতা ও সিজদার সুবর্ণ সুন্নাত আদব:\n\n১. সিজদায় অঙ্গ-প্রত্যঙ্গের অবস্থান:\nসিজদায় মোট ৭টি অঙ্গ মাটিতে রাখা ফরজ: কপাল ও নাক একত্রে, দুই হাতের তালু, দুই হাঁটু এবং দুই পায়ের আঙুলসমূহ কিবলামুখী করে ভাজ করে রাখা (সহীহ বুখারী: ৮১২)। দুই হাত মাটি থেকে ও পেট উরু থেকে ফাঁকা রাখতে হবে।\n\n২. দৃষ্টি রাখার সঠিক স্থান:\nদাঁড়ানো অবস্থায় সিজদার স্থানে, রুকুতে পায়ের পাতার ওপর, সিজদায় নাকের ডগায় এবং তাশাহহুদে তর্জনী আঙুলের দিকে দৃষ্টি রাখা একাগ্রতা ধরে রাখতে সাহায্য করে।\n\n৩. সালাত আদায়ের ৩টি নিষিদ্ধ সময়:\nসূর্যোদয়ের সময়, ঠিক দ্বিপ্রহরের সময় (সূর্য ঠিক মাথার ওপর থাকা অবস্থায়) এবং সূর্যাস্তের সময়—এই তিন ওয়াক্তে যেকোনো সালাত আদায় করা ও সিজদা করা সম্পূর্ণ নিষিদ্ধ (সহীহ মুসলিম: ৮৩৭)।",
