                arabicText = "أَوَّلُ مَا يُحَاسَبُ الْعَبْدُ يَوْمَ الْقِيَامَةِ الصَّلَاةُ فَإِنْ صَلَحَتْ صَلَحَ سَائِرُ عَمَلِهِ وَإِنْ فَسَدَتْ فَسَدَ سَائِرُ عَمَلِهِ ۞ وَمَا تَقَرَّبَ إِلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ",
                pronunciationBn = "আওওয়ালু মা- ইউহা-সাবুল 'আবদু yawমাল ক্বিয়া-মাতিছ ছলা-তু, ফা-ইন সলাহাত সলাহা সা-য়িরু 'আমালিহী, ওয়া ইন ফাসাদাত ফাসাদা সা-য়িরু 'আমালিহ। ... ওয়া মা তাক্বররাবা ইলাইয়্যা 'আবদী বিশাই-ইন আহাব্বা ইলাইয়্যা মিম্মাফ তারাদ্ধতু 'আলাইহি, ওয়া মা ইয়াঝা-লু 'আবদী ইয়াতাক্বররাবু ইলাইয়্যা বিন নাওয়া-ফিলি হাত্তা- উহিব্বাহ্।",
                meaningBn = "\"(১) কিয়ামতের দিন বান্দার নিকট থেকে সর্বাগ্রে যে আমলের হিসাব নেওয়া হবে তা হলো সালাত। সুতরাং সালাত সঠিক ও পরিপূর্ণ হয়ে থাকলে সে সফলকাম হবে ও তার অন্যান্য সকল আমলও সঠিক বলে বিবেচিত হবে; নচেৎ ব্যর্থ ও ক্ষতিগ্রস্ত হবে।\n(২) হাদিসে কুদসীতে আল্লাহ তা'আলা বলেন: 'আমার বান্দা যা কিছু দিয়ে আমার নৈকট্য লাভ করে তার মধ্যে আমার প্রিয়তম হলো যা আমি তার ওপর ফরজ করেছি। আর বান্দা নফল ইবাদত দ্বারা অনবরত আমার নৈকট্য অর্জন করতে থাকে, পরিশেষে আমি তাকে ভালোবাসি...'\"",
                fojilotBn = "📖 প্রামাণ্য হাদীস গ্রন্থসমূহের বিশ্লেষণ ও গভীর তাৎপর্য:\n\n১. সর্বাগ্রে সালাতের হিসাব (আব্দুল্লাহ বিন কুরত ও আবূ হুরায়রা রা. বর্ণিত):\nরাসূলুল্লাহ (ﷺ) ইরশাদ করেছেন: কিয়ামতের দিন মানুষের আমলের মধ্যে সর্বপ্রথম সালাতের হিসাব-নিকাশ নেওয়া হবে। যদি সালাত পরিপূর্ণ রূপে পাওয়া যায়, তবে তা পরিপূর্ণ লেখা হবে। যদি কোনো ঘাটতি বা কমতি থাকে, তখন মহামহিম আল্লাহ ফেরেশতাদের বলবেন: \"দেখ, আমার বান্দার কোনো নফল সালাত আছে কি না?\" অতঃপর নফল সালাত দ্বারা ফরজ সালাতের ক্ষতিপূরণ ও ঘাটতি পূর্ণ করে দেওয়া হবে। এরপর অন্যান্য আমলের ক্ষেত্রেও অনুরূপ হিসাব গ্রহণ করা হবে।\n[সুনান নাসাঈ: ৪৬৬, ৪৬৭, ৪৬৮; জামে আত-তিরমিযী: ৪১৩; সুনান আবু দাউদ: ৮৬৪; সুনান ইবনু মাজাহ: ১৪২৫; ত্বাবারানীর আওসাত্ব: ১৮৫৯; সহীহ আত-তারগীব: ১/১৮৫]\n\n২. আল্লাহর ওলীর হাদিসে কুদসী ও নফলের মর্যাদা (সহীহ বুখারী: ৬৫০২):\nমহানবী (ﷺ) বলেন, আল্লাহ তা'আলা ইরশাদ করেছেন:\n\"যে ব্যক্তি আমার ওলীর বিরুদ্ধে শত্রুতা পোষণ করবে, আমি তার বিরুদ্ধে যুদ্ধ ঘোষণা করব। বান্দা যা কিছু দিয়ে আমার নৈকট্য লাভ করে থাকে তার মধ্যে আমার নিকট প্রিয়তম হলো সেই ইবাদত, যা আমি তার ওপর ফরজ করেছি। আর সে নফল ইবাদত দ্বারা আমার নৈকট্য অর্জন করতে থাকে; পরিশেষে আমি তাকে ভালোবাসি। অতঃপর আমি তার শোনার কান হয়ে যাই, তার দেখার চোখ হয়ে যাই, তার ধরার হাত হয়ে যাই, তার চলার পা হয়ে যাই! সে আমার কাছে কিছু চাইলে আমি অবশ্যই তাকে তা দান করি। সে আমার কাছে আশ্রয় প্রার্থনা করলে আমি অবশ্যই তাকে আশ্রয় দিয়ে থাকি...\" [সহীহ বুখারী: ৬৫০২]\n\n৩. অর্থ ব্যাখ্যা:\nআল্লাহ বান্দার কান, চোখ, হাত ও পা হওয়ার অর্থ হলো—বান্দা আল্লাহর সন্তুষ্টি মোতাবেকই তার প্রতিটি অঙ্গ-প্রত্যঙ্গ ব্যবহার করে। যাতে ব্যবহার করলে আল্লাহ অসন্তুষ্ট হন, বান্দা কখনোই সে কাজে ঐ সকল অঙ্গ ব্যবহার করে না।",
                detailsBn = "ফরজ সালাতের পর নফল সালাত আদায় করা বান্দাকে আল্লাহর প্রিয় ওলীতে পরিণত করে এবং কিয়ামতের ময়দানে ঘাটতি পূরণের মহাসম্ভার গড়ে তোলে।",
                referenceBn = "সহীহ বুখারী: ৬৫০২; সুনান নাসাঈ: ৪৬৬, ৪৬৭, ৪৬৮; জামে আত-তিরমিযী: ৪১৩; সুনান আবু দাউদ: ৮৬৪; সুনান ইবনু মাজাহ: ১৪২৫; ত্বাবারানীর আওসাত্ব: ১৮৫৯"
            ),

