                meaningBn = "\"যে ব্যক্তি কোনো সালাত আদায় করতে ভুলে যায় অথবা ঘুমিয়ে পড়ে, তবে তার কাফফারা হলো স্মরণ হওয়া মাত্রই তা পড়ে নেওয়া; এ ছাড়া তার আর কোনো কাফফারা (প্রায়শ্চিত্ত) নেই। এবং আল্লাহ বলেন: 'আর আমাকে স্মরণ করার উদ্দেশ্যে সালাত কায়েম করো' [সূরা ত্বা-হা: ১৪]।\"",
                fojilotBn = "📖 ফিকহুস সুন্নাহ ও সহীহ হাদিস ভিত্তিক কাযা সালাতের নীতিমালা:\n\n১. স্মরণ হওয়ামাত্রই সর্বাগ্রে সালাত কাযা করা জরুরি:\nরাসূলুল্লাহ (ﷺ) বলেন: \"যে ব্যক্তি কোনো সালাত পড়তে ভুলে যায় অথবা ঘুমিয়ে পড়ে, তাহলে তার কাফফারা হলো স্মরণ হওয়া মাত্র তা পড়ে নেওয়া\" (সহীহ বুখারী: ৫৯৭, সহীহ মুসলিম: ৬৮৪, মিশকাত: ৬০৩)। অতএব কাযা সালাত পড়ার জন্য কোনো নির্দিষ্ট সময়-অসময় নেই। দিবা-রাত্রের যে কোনো সময়ে চেতন হলে বা মনে পড়লেই বিলম্ব না করে অবিলম্বে সালাত আদায় করে নেওয়া ওয়াজিব; পরবর্তী ওয়াক্ত পর্যন্ত অপেক্ষা করা জায়েয নয়।\n\n২. ঘুমে কোনো শৈথিল্য নেই:\nনবীজী (ﷺ) আরো বলেন: \"নিদ্রা অবস্থায় কোনো শৈথিল্য নেই। শৈথিল্য তো জাগ্রত অবস্থায় হয়। সুতরাং যখন তোমাদের কেউ কোনো সালাত পড়তে ভুলে যায় বা ঘুমিয়ে পড়ে, তখন তার উচিত স্মরণ হওয়ামাত্র তা পড়ে নেওয়া\" (সহীহ মুসলিম: ৬৮১, মিশকাত: ৬০৪)।\n\n৩. ইচ্ছাকৃত বিনা ওজরে সালাত ছেড়ে দেওয়ার বিধান:\nবিনা ওজরে ইচ্ছাকৃত সালাত ছেড়ে দিলে বা সুযোগ ও সময় থাকা সত্ত্বেও না পড়ে অন্য ওয়াক্ত এসে গেলে চরম কবিরা গুনাহ হবে। বিনা ওজরে যথাসময়ে সালাত না পড়ে অন্য সময়ে শুধু কাযা পড়ায় দায়িত্ব পূর্ণ হয় না; বরং এর জন্য খাঁটি মনে আল্লাহর দরবারে তওবা-ইস্তেগফার করতে হবে এবং বেশি বেশি নফল সালাত আদায় করে ফরজের ঘাটতি পূরণ করতে হবে (ফিকহুস সুন্নাহ: ১/২৪১-২৪৩; আল-মুহাল্লা)।\n\n৪. অজ্ঞান বা বেহুশ ব্যক্তির কাযা বিধান:\nকেউ অসুস্থতা বা দুর্ঘটনায় অজ্ঞান বা অচেতন থাকলে জ্ঞান ফিরে আসার পর সেই অজ্ঞানকালীন সালাত কাযা পড়তে হবে না; কারণ সে তখন জ্ঞানহীন মাজুর ব্যক্তির পর্যায়ভুক্ত (সুনান আবু দাউদ, সুনান আত-তিরমিযী, মিশকাত: ৩২৮৭)। হযরত আব্দুল্লাহ ইবনে উমার (রা.) অজ্ঞান অবস্থায় কোনো সালাত ছুটে গেলে জ্ঞান ফেরার পর তা কাযা পড়তেন না (মুসান্নাফ আব্দুর রাযযাক: হা/২০৮০; আল-মুমতে' শারহুল ফিকহ: ২/১২৬)।",
                detailsBn = "ঘুম বা ভুলে সালাত ছুটে গেলে স্মরণ হওয়ামাত্রই আদায় করতে হবে। অলসতাবশত কখনোই সালাত কাযা করা যাবে না।",
                referenceBn = "সহীহ বুখারী: ৫৯৭; সহীহ মুসলিম: ৬৮১, ৬৮৪; সুনান আবু দাউদ: ৪৩৭, ৩২৮৭; জামে আত-তিরমিযী: ১৭৭; মিশকাতুল মাসাবীহ: ৬০৩, ৬০৪; ফিকহুস সুন্নাহ: ১/২৪১-২৪৩"
