                arabicText = "اللَّهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَى عَذَابَكَ، إِنَّ عَذَابَكَ بِالْكَافِرِينَ مُلْحَقٌ، اللَّهُمَّ إِنَّا نَسْتَعِينُكَ، وَنَسْتَغْفِرُكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَلَا نَكْفُرُكَ، وَنُؤْمِنُ بِكَ، وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفُرُكَ\n\nسُبْحَانَ الْمَلِكِ الْقُدُّوسِ ۞ رَبِّ الْمَلَائِكَةِ وَالرُّوحِ",
                pronunciationBn = "আল্লা-হুম্মা ইয়্যা-কা না‘বুদু, ওয়ালাকা নুসল্লী ওয়া নাসজুদু, ওয়া ইলাইকা নাস‘আ- ওয়া নাহফিদু, নারজূ রহমাতাকা, ওয়া নাখশা- ‘আযা-বাকা, ইন্না ‘আযা-বাকা বিলকা-ফিরীনা মুলহাক্ব। আল্লা-হুম্মা ইন্না- নাসতা‘ঈনুকা ওয়া নাসতাগফিরুকা, ওয়া নুছনী ‘আলাইকাল খাইরা, ওয়ালা- নাকফুরুকা, ওয়া নু’মিনু বিকা, ওয়া নাখদ্বা‘উ লাকা, ওয়া নাখলা‘উ মাইঁ ইয়াকফুরুক।\n\nসালামের পর: সুবহা-নাল মালিকিল ক্বুদ্দূস (৩ বার, ৩য় বারে টেনে উচ্চৈঃস্বরে পাঠ) এবং সাথে 'রব্বিল মালা-ইকাতি ওয়ার রূহ'।",
                meaningBn = "\"হে আল্লাহ! আমরা আপনারই ইবাদত করি; আপনার জন্যই সালাত আদায় করি ও সিজদা করি; আমরা আপনার দিকেই দৌড়াই এবং দ্রুত অগ্রসর হই; আমরা আপনার করুণা লাভের আকাঙ্ক্ষা করি এবং আপনার শাস্তিকে ভয় করি। নিশ্চয়ই আপনার শাস্তি কাফেরদেরকে পাবে। হে আল্লাহ! নিশ্চয়ই আমরা আপনার কাছে সাহায্য চাই, আপনার কাছে ক্ষমা চাই, আপনার উত্তম প্রশংসা করি, আপনার সাথে কুফরি করি না, আপনার ওপর ঈমান আনি, আপনার প্রতি অনুগত হই, আর যে আপনার সাথে কুফরি করে আমরা তার সাথে সম্পর্ক ছিন্ন করি।\n\nসালামের পর: কতই না পবিত্র-মহান সেই মহাপবিত্র মহাশাসক বাদশাহ! যিনি ফেরেশতাকুল ও জিবরীল (আ.)-এর প্রতিপালক রব।\"",
                fojilotBn = "📖 সহীহ হাদীসের সনদ ও আমলের সুন্নাত পদ্ধতি:\n\n১. হযরত উমর (রা.) বর্ণিত বিশুদ্ধ কুনূতে বিত্র:\nইমাম বায়হাকী তাঁর 'আস-সুনানুল কুবরা' গ্রন্থে (২/২১১) হাদীসটি সংকলন করেছেন এবং সনদকে বিশুদ্ধ বলেছেন। শাইখ আলবানী 'ইরওয়াউল গালীল' (২/১৭০)-এ বলেন: \"এর সনদ বিশুদ্ধ এবং তা হযরত উমর (রা.) থেকে মওকূফ সূত্রে বিশুদ্ধভাবে প্রমাণিত।\" বিতরের সালাতে রুকুর পূর্বে বা পরে এই দো'আটি পাঠ করা অত্যন্ত বরকতময় সুন্নাত।\n\n২. বিত্র সালাতে সালাম ফিরানোর পরের মাসনূন যিকির:\nরাসূলুল্লাহ (ﷺ) বিতরের সালাত শেষে তিনবার বলতেন: 'سُبْحَانَ الْمَلِكِ الْقُدُّوسِ' (সুবহানাল মালিকিল কুদ্দূস)। তৃতীয়বারে তিনি স্বর টেনে উচ্চৈঃস্বরে দীর্ঘ করে বলতেন এবং সাথে যোগ করতেন: 'رَبِّ الْمَلَائِكَةِ وَالرُّوحِ' (রব্বিল মালাইকাতি ওয়ার রূহ)।\n[সুনান নাসাঈ: ৩/২৪৪, হা/১৭৩৪; সুনান আবু দাউদ: ১৪৩০; সুনান দারাকুতনী: ২/৩১; যাদুল মা'আদ: ১/৩৩৭]",
                detailsBn = "বিতরের সালাত হলো রাতের সালাতের পূর্ণতাদানকারী বিশেষ সালাত। কুনূত ও সালামের পরের এই যিকির মহান রবের মহাশাসকত্বের পূর্ণাঙ্গ স্বীকারোক্তি।",
                referenceBn = "আস-সুনানুল কুবরা লিল-বায়হাকী: ২/২১১; ইরওয়াউল গালীল: ২/১৭০; সুনান নাসাঈ: ১৭৩৪; সুনান আবু দাউদ: ১৪৩০; সুনান দারাকুতনী: ২/৩১; যাদুল মা'আদ: ১/৩৩৭"
            ),

