                arabicText = "إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا ۞ مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللَّهِ ۞ رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا",
                pronunciationBn = "ইন্না ক্বুরআ-নাল ফাজরি কা-না মাশহূদা-। মান সল্লাছ ছুবহা ফাহুওয়া ফী যিম্মাতিল্লা-হ। রাক'আতাল ফাজরি খাইরুম মিনাদ্ দুনইয়া- ওয়া মা- ফীহা-।",
                meaningBn = "\"নিশ্চয়ই ফজরের কুরআন পাঠ (সালাত) প্রত্যক্ষভাবে ফেরেশতাদের উপস্থিতির সাক্ষ্যপ্রাপ্ত। [সূরা বনী ইসরাঈল: ৭৮] • যে ব্যক্তি ফজরের সালাত আদায় করে, সে ঐ দিন আল্লাহর প্রত্যক্ষ দায়িত্ব ও জিম্মাদারীতে চলে যায়। [সহীহ মুসলিম: ৬৫৭] • ফজরের দুই রাকাত সুন্নাত গোটা দুনিয়া ও তার মধ্যকার সবকিছুর চেয়ে উত্তম। [সহীহ মুসলিম: ৭২৫]\"",
                fojilotBn = "📖 সিহাহ সিত্তাহ সহীহ হাদীসের আলোকে ফজরের ৭টি অনন্য ফযীলত ও মর্যাদা:\n\n১. মুমিন ও মুনাফিকের পার্থক্য:\nরাসূলুল্লাহ (ﷺ) ইরশাদ করেছেন: \"মুনাফিকদের জন্য ফজর ও এশার চেয়ে ভারী সালাত আর নেই। তারা যদি জানত এ দুই সালাতে কী সাওয়াব রয়েছে, তবে হামাগুড়ি দিয়ে হলেও উপস্থিত হতো\" (সহীহ বুখারী: ৬৪৪, ৬৫৭, ২৪২০, ৭২২৪; সহীহ মুসলিম: ৬৫১)।\n\n২. আল্লাহর সরাসরি জিম্মাদারী ও কুদরতী নিরাপত্তা লাভ:\nযে ব্যক্তি ফজরের সালাত আদায় করে, সে ব্যক্তি ঐ দিন আল্লাহর জিম্মায় চলে যায়। অর্থাৎ স্বয়ং আল্লাহ তা'আলা ঐ ব্যক্তির সার্বিক সুরক্ষা ও রিজিকের দায়িত্ব নেন (জামে আত-তিরমিযী: ২১৮৪; সহীহ মুসলিম: ৬৫৭)।\n\n৩. সারারাত দাঁড়িয়ে নফল সালাতের সাওয়াব:\nরাসূলুল্লাহ (ﷺ) বলেছেন: \"যে ব্যক্তি জামা'আতের সাথে ফজরের সালাত আদায় করে, আল্লাহ তা'আলা তার আমলনামায় দাঁড়িয়ে সারারাত নফল সালাত আদায়ের সমপরিমাণ সওয়াব দান করেন\" (সহীহ মুসলিম: ৬৫৬, হা/১০৯৬)।\n\n৪. কিয়ামতের দিন চতুর্দিক আলোকিতকারী পূর্ণাঙ্গ নূর:\n\"যে ব্যক্তি ভোরে অন্ধকারে হেঁটে হেঁটে ফজরের সালাত আদায়ের জন্য মসজিদে প্রবেশ করবে, আল্লাহ তা'আলা কিয়ামতের দিন তার জন্য পরিপূর্ণ আলো ও নূর দান করবেন\" (সুনান আবু দাউদ: ৪৯৪; জামে আত-তিরমিযী: ২২৩)।\n\n৫. জান্নাতের শ্রেষ্ঠতম নিয়ামত — স্বচক্ষে মহান আল্লাহর পবিত্র দিদার লাভ:\nযে ব্যক্তি নিয়মিত ফজরের সালাত আদায় করবে, আল্লাহ তাকে জান্নাতের সবচেয়ে বড় নিয়ামত দান করবেন—অর্থাৎ সে আল্লাহর দর্শন লাভ করবে। জান্নাতী ব্যক্তি আল্লাহকে পূর্ণিমার রাতের আকাশের উজ্জ্বল চাঁদের মতো স্পষ্ট দেখতে পাবে (সহীহ বুখারী: ৫৭৩; সহীহ মুসলিম: ৬৩৩)।\n\n৬. দুনিয়া ও তার মধ্যস্থিত সবকিছুর চেয়ে শ্রেষ্ঠ:\n\"ফজরের দু রাকাত সুন্নাত দুনিয়া ও তার মাঝে যা কিছু আছে তারচেয়েও উত্তম ও মূল্যবান\" (সহীহ মুসলিম: ৭২৫/৭৫০; জামে আত-তিরমিযী: ৪১৬)।\n\n৭. জাহান্নাম থেকে চিরন্তন মুক্তি ও জান্নাতের গ্যারান্টি:\nরাসূলুল্লাহ (ﷺ) ঘোষণা করেন: \"যে নিয়মিত সূর্যোদয়ের পূর্বে (ফজর) ও সূর্যাস্তের পূর্বে (আসর) সালাত আদায় করবে, সে কখনই জাহান্নামে প্রবেশ করবে না\" (সহীহ মুসলিম: ৬৩৪; সুনান আবু দাউদ: ৪২৭)।",
                detailsBn = "ফজরের সালাতের মাধ্যমে মুমিনের দিন শুরু হয় আল্লাহর অভিভাবকত্বে। মুনাফিকীর তকমা ছিন্ন করতে ফজরের জামা'আতের কোনো বিকল্প নেই।",
                referenceBn = "সূরা বনী ইসরাঈল: ৭৮; সহীহ বুখারী: ৫৭৩, ৬৪৪, ৬৫৭, ২৪২০, ৭২২৪; সহীহ মুসলিম: ৬৩৪, ৬৫১, ৬৫৬, ৬৫৭, ৭২৫, ১০৯৬; জামে আত-তিরমিযী: ২২৩, ৪১৬, ২১৮৪; সুনান আবু দাউদ: ৪২৭, ৪৯৪"
            ),

