                arabicText = "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ\n\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ",
                pronunciationBn = "আত্তাহিয়্যা-তু লিল্লা-হি ওয়াছ ছলাওয়া-তু ওয়াত্ব ত্বইয়্যিবা-তু, আসসালা-মু ‘আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রহ্মাতুল্লা-হি ওয়া বারাকা-তুহ, আসসালা-মু ‘আলাইনা- ওয়া ‘আলা- ‘ইবা-দিল্লা-হিছ ছ-লিহীন। আশহাদু আল লা- ইলা-হা ইল্লাল্লা-হু, ওয়া আশহাদু আন্না মুহাম্মাদান ‘আবদুহূ ওয়া রাসূলুহ্।\n\nআল্লা-হুম্মা ছল্লি ‘আলা- মুহাম্মাদিঁও ওয়া ‘আলা- আ-লি মুহাম্মাদ, কামা- ছল্লাইতা ‘আলা- ইবরা-হীমা ওয়া ‘আলা- আ-লি ইবরা-হীম, ইন্নাকা হামীদুম মাজীদ। আল্লা-হুম্মা বা-রিক ‘আলা- মুহাম্মাদিঁও ওয়া ‘আলা- আ-লি মুহাম্মাদ, কামা- বা-রকতা ‘আলা- ইবরা-হীমা ওয়া ‘আলা- আ-লি ইবরা-হীম, ইন্নাকা হামীদুম মাজীদ।",
                meaningBn = "\"যাবতীয় অভিবাদন, যাবতীয় সালাত ও সমস্ত পবিত্র বস্তু আল্লাহর জন্য। হে নবী! আপনার প্রতি শান্তি, আল্লাহর রহমত ও তাঁর বরকতসমূহ বর্ষিত হোক। শান্তি আমাদের প্রতি এবং আল্লাহর নেক বান্দাদের প্রতি বর্ষিত হোক। আমি সাক্ষ্য দিচ্ছি যে, আল্লাহ ছাড়া কোনো সত্য উপাস্য নেই; এবং আরও সাক্ষ্য দিচ্ছি যে, নিশ্চয়ই মুহাম্মাদ তাঁর বান্দা ও তাঁর রাসূল।\n\nহে আল্লাহ! আপনি মুহাম্মাদ (ﷺ) এবং তাঁর পরিবারের ওপর রহমত বর্ষণ করুন, যেমন আপনি ইবরাহীম (আ.) ও তাঁর পরিবারের ওপর রহমত বর্ষণ করেছিলেন; নিশ্চয় আপনি প্রশংসিত ও মহিমান্বিত। হে আল্লাহ! আপনি মুহাম্মাদ (ﷺ) এবং তাঁর পরিবারের ওপর বরকত নাযিল করুন, যেমন আপনি ইবরাহীম (আ.) ও তাঁর পরিবারের ওপর বরকত নাযিল করেছিলেন; নিশ্চয় আপনি প্রশংসিত ও মহিমান্বিত।\"",
                fojilotBn = "📖 সহীহ হাদীসের আলোকে তাশাহহুদ ও দরূদের তাৎপর্য:\n\n১. কুরআন শিক্ষার মতো তাশাহহুদ শিক্ষা:\nহযরত আব্দুল্লাহ ইবনে মাসঊদ (রা.) বলেন: \"রাসূলুল্লাহ (ﷺ) আমার হাত তাঁর দু'হাতের মাঝে রেখে আমাকে তাশাহহুদ শিখিয়েছেন, যেভাবে তিনি আমাদেরকে কুরআনের সূরা শিক্ষা দিতেন\" (সহীহ বুখারী: ৬২৬৫, সহীহ মুসলিম: ৪০২)।\n\n২. ১০টি রহমত, ১০টি গুনাহ মাফ ও ১০টি মর্যাদা বৃদ্ধি:\nরাসূলুল্লাহ (ﷺ) ইরশাদ করেছেন: \"যে ব্যক্তি আমার ওপর একবার দরূদ পাঠ করে, মহান আল্লাহ তার ওপর দশটি রহমত নাযিল করেন, তার দশটি গুনাহ মাফ করে দেন এবং তার জন্য দশটি মর্যাদা বৃদ্ধি করেন\" (সুনান আন-নাসাঈ: ১২৯৭; সহীহুত তারগীব: ১/১৬৬ - সহীহ)।\n\n৩. দো'আ কবুলের চাবিকাঠি:\nসালাতের শেষ বৈঠকে তাশাহহুদ ও দরূদের পর দো'আ পাঠ করলে সে দো'আ আল্লাহ তা'আলা কবুল করে নেন।",
